/* 08 chat */
.chat{display:flex;flex-direction:column;height:400px}
.msgs{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:14px;scroll-behavior:smooth;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.m-user{align-self:flex-end;max-width:82%;background:var(--chip);padding:8px 12px;font-size:14px}
.m-agent{display:flex;flex-direction:column;gap:8px;max-width:92%}
.rchips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.rchip{display:inline-flex;align-items:center;gap:6px;padding:2px 8px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted)}
.rchip .ms{font-size:13px;color:var(--accent)}
.m-text{font-size:14px;line-height:1.6}
.chat-in{display:flex;align-items:center;gap:8px;padding:10px;border-top:1px solid var(--line)}
.chat-in input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:14px;padding:6px}
.chat-in input::placeholder{color:var(--muted)}

/* thread panel chips */
#chat-msgs .rchip{cursor:pointer;transition:border-color .2s,background-color .2s,color .2s}
#chat-msgs .rchip:hover{border-color:var(--icon-line);color:var(--text)}
.rc-tip{position:absolute;z-index:6;display:flex;flex-direction:column;gap:1px;width:190px;padding:9px 11px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 14px 34px -16px rgba(0,0,0,.4);opacity:0;transform:translateY(4px);transition:opacity .15s ease,transform .25s var(--ease);pointer-events:none}
.rc-tip.show{opacity:1;transform:none}
.rc-tip .t{font-size:13px;font-weight:600;color:var(--text)}
.rc-tip .d{font-size:11.5px;color:var(--muted)}
.rc-tip .o{margin-top:4px;font-size:11px;font-weight:600;color:var(--accent)}
[data-style="soft"] .rc-tip{border-radius:12px;border-color:var(--line)}

/* ---------- 08 chat ---------- */
{
  const msgs = $('#chat-msgs'), input = $('#chat-input'), send = $('#chat-send');
  const convos = {
    onboarding: [
      { u:'Why is the workspace step losing people?' },
      { a:'It asks for a team name before anyone has created anything. Moving it after the first project should help, and the name can default to the email domain.', chips:[['grid_on','Funnel data'],['description','Session notes']], t:'4s' }
    ],
    tokens: [
      { u:'Are the new spacing tokens applied everywhere?' },
      { a:'Nine of twelve frames use them. The pricing, footer and modal frames still have hardcoded values, so I can swap those next.', chips:[['dashboard','Figma file'],['code','tokens.css']], t:'3s' }
    ]
  };
  const replies = [
    { a:'Done, I added that to the handoff notes and tagged the web team.', chips:[['folder','Workspace']], t:'2s' },
    { a:'Got it. I will check the remaining frames and flag anything off the 8px grid.', chips:[['dashboard','Figma file']], t:'3s' }
  ];
  let cur = 'onboarding', rIdx = 0, busy = false, ts = [];
  const scroll = () => { msgs.scrollTop = msgs.scrollHeight; };
  function agentEl(m, animate){
    const el = document.createElement('div'); el.className = 'm-agent' + (animate ? ' enter' : '');
    el.innerHTML = `<div class="rchips">${m.chips.map(c => `<span class="rchip">${ic(c[0])}${c[1]}</span>`).join('')}<span class="rchip">for ${m.t}</span></div><div class="m-text">${animate ? wordsHTML(m.a) : m.a}</div>`;
    return el;
  }
  function userEl(text){ const el = document.createElement('div'); el.className = 'm-user enter'; el.textContent = text; return el; }
  function load(key){
    ts.forEach(clearTimeout); ts = []; busy = false; cur = key;
    msgs.style.transition = 'opacity .2s ease'; msgs.style.opacity = '0';
    setTimeout(() => {
      msgs.innerHTML = '';
      convos[key].forEach(m => msgs.appendChild(m.u ? userEl(m.u) : agentEl(m, false)));
      msgs.style.opacity = '1'; scroll();
    }, 200);
  }
  function sendMsg(){
    const v = input.value.trim(); if (!v || busy) return;
    busy = true; input.value = ''; send.disabled = true; Sound.play('send');
    convos[cur].push({ u:v }); msgs.appendChild(userEl(v)); scroll();
    const think = document.createElement('div'); think.className = 'rchips enter'; think.innerHTML = '<span class="rchip shimmer" style="border-color:var(--line)">Thinking</span>';
    ts.push(setTimeout(() => { msgs.appendChild(think); scroll(); }, 350));
    ts.push(setTimeout(() => {
      think.remove(); const m = replies[rIdx++ % replies.length]; convos[cur].push(m);
      const el = agentEl(m, true); msgs.appendChild(el); scroll();
      const r = revealWords(el, 40, i => { if (i % 3 === 0) Sound.play('stream'); scroll(); });
      ts.push(setTimeout(() => { busy = false; Sound.play('pop'); }, r.done + 200));
    }, 1500));
  }
  input.addEventListener('input', () => { send.disabled = !input.value.trim(); });
  input.addEventListener('keydown', e => { if (e.key === 'Enter'){ e.preventDefault(); sendMsg(); } });
  send.addEventListener('click', sendMsg);
  initInTabs($('#chat-tabs'), load);
  load('onboarding');
}

/* ---------- thread panel chips ---------- */
{
  const msgs = $('#chat-msgs'), panel = msgs.closest('.panel');
  const tip = document.createElement('div'); tip.className = 'rc-tip'; panel.style.position = 'relative'; panel.appendChild(tip);
  const INFO = { 'Funnel data':'Segment, last 30 days', 'Session notes':'Notion, 8 sessions', 'Token audit':'Figma, 12 frames', 'Frames list':'Figma, 3 frames left' };
  msgs.addEventListener('mouseover', e => {
    const c = e.target.closest('.rchip'); if (!c) return;
    const name = c.textContent.trim(), pr = panel.getBoundingClientRect(), r = c.getBoundingClientRect();
    tip.innerHTML = `<span class="t">${name}</span><span class="d">${INFO[name] || 'Attached source'}</span><span class="o">Click to open</span>`;
    tip.style.left = Math.max(8, Math.min(pr.width - 200, r.left - pr.left)) + 'px'; tip.style.top = (r.top - pr.top - 64) + 'px'; tip.classList.add('show');
  });
  msgs.addEventListener('mouseout', e => { if (e.target.closest('.rchip')) tip.classList.remove('show'); });
  msgs.addEventListener('click', e => { const c = e.target.closest('.rchip'); if (c){ Sound.play('tab'); showToast('Opening ' + c.textContent.trim()); } });
}
